"Epochs": "轮数",
"How many epochs: every track of the set once an epoch, one track a step; the run's steps are the set's tracks times this. A small set is learnt by heart fast: the green epochs in the Telemetry are the ones to hear first, often before the last.": "训练多少轮：每轮把集里的每首曲目各过一遍，一步一首；运行的总步数 = 集里的曲目数 × 这个数。小数据集很快会被背下来：遥测里的绿色轮次先听，往往比最后一轮更好。",
