"adapter": "适配器",
"Most often this is strength past the ceiling: bring the music strengths into the green, take an adapter off the music half (its sound half can stay), or generate in Direct mode, which writes no score at all.": "最常见的原因是强度超过上限：把音乐强度调回绿区，从音乐一半上撤下一个适配器（它的声音一半可以保留），或者用完全不写乐谱的直接模式生成。",
"No adapter weighed on the music half: the score sampling may be too hot (temperature, top-k). Reset sampling, or try another seed.": "没有适配器压在音乐一半上：乐谱采样可能太热了（温度、top-k）。重置采样，或换个种子试试。",
