"As the studio made it (and the Refiner finished it), no DAW in between.": "就是工作室做出的样子（经精修室收尾），中间不经过 DAW。",
"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "就是工作室做出的样子（经精修室收尾），中间不经过 DAW。手头的录音：",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "打开一个录音、播放一个，或在资料馆中勾选一个：它的 WAV、FLAC 和 MP3 会出现在这里。",
"Into your DAW": "放进你的 DAW",
"experimental": "实验性",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "能用且已检查过，但仍需在其他机器和项目上做压力测试，还需要更多工作",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "把整个录音作为你 DAW 的项目：分轨在各自的轨道上，乐谱为 MIDI，速度，段落为区域，歌词在时间线上。你用哪个 DAW？",
"Asking the lab…": "正在询问实验室…",
"The lab does not answer: {0}": "实验室没有响应：{0}",
"✓ on the studio’s machine": "✓ 在工作室的机器上",
"✓ on the studio’s machine · {0}": "✓ 在工作室的机器上 · {0}",
"not on the studio’s machine; on your own computer it may well be": "不在工作室的机器上；在你自己的电脑上可能有",
"How to install it": "如何安装",
"Your DAW ✓": "你的 DAW ✓",
"I use this one": "我用这个",
"Export the take": "导出录音",
"A DAWproject: the mix, the stems, the score as notes, the sections as markers": "一个 DAWproject：混音、分轨、作为音符的乐谱、作为标记的段落",
"first": "首先",
"next": "其次",
"Now: the": "现在：",
"project (the mix, every stem, the score as MIDI; the lyrics and sections once the take is timed in the Refiner’s lyrics check), and": "项目（混音、每个分轨、作为 MIDI 的乐谱；歌词和段落要等录音在精修室的歌词检查里对好时间之后），以及",
"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "（混音、每个分轨、作为音符的乐谱、作为标记的段落：Waveform 14、Bitwig、Studio One、Cubase）；两者也都在录音菜单 → 下载 中。Waveform：14 或更新版本。",
"Packing…": "正在打包…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 天全功能试用，之后需要许可证：个人或小企业 60 美元",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 或更新版本：免费，不限轨道和导出；能打开工作室的 DAWproject（File > Import Other > Import a DAWproject file）。不支持 Waveform 13",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "注册后 30 天无限制，之后 Essentials 99 美元、Producer 199 美元或 Studio 399 美元（bitwig.com，03.10.2026）；能打开工作室的 DAWproject：混音、分轨、作为音符的乐谱、作为标记的段落",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → Linux x86_64 的 tarball → 解压后运行 ./install-reaper.sh（装到 /opt/REAPER）",
"tracktion.com/products/waveform-free → the .deb of Waveform 14 for Linux → sudo apt install ./waveform14_*.deb": "tracktion.com/products/waveform-free → Linux 版 Waveform 14 的 .deb → sudo apt install ./waveform14_*.deb",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download：Ubuntu 的 .deb（sudo apt install ./bitwig-studio-*.deb）或 Flatpak",
