"No LoRAs found. Put .safetensors files (or folders, or links to them) in the app's loras/ folder.": "没有找到 LoRA。把 .safetensors 文件（或文件夹，或指向它们的链接）放进应用的 loras/ 文件夹。",
"{0} is no longer in loras/ and will be left out.": "{0} 已不在 loras/ 中，将被略过。",
