"{0} was trained with a score ({1} mode).": "{0} 是带乐谱训练的（{1} 模式）。",
"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}：音乐部分的 {1} 超过了上限 {2}：乐谱往往在 70-200 个令牌后失败。",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}：声音部分的 {1} 超过了上限 {2}。",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} 规划的是器乐乐谱：在 {1} 且有要唱的歌词时，乐谱会丢掉人声线（在 1.00 测得：127 个人声小节里只有 1 个音符，音乐循环）。唱的歌请保持低值，0.3–0.5。",
"{#0} stacked: their changes add up.": "叠加了 {#0} 个：它们的改变会相加。",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ 音乐部分合计为 {0}，超过了共同上限 {1}：这么重的运行每次都写出坏的乐谱（已测得）。降低几个，或把一个从音乐部分拿掉。",
