"Listen to {0}": "听 {0}",
"Listen to {0}?": "听 {0}？",
"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni 会听每条音轨 120 秒并起草其风格。之前听过的草稿另存一边（styles.DATE.json）；只有你写入时描述才会改变。",
"Listen": "听",
"Listening to {0}": "正在听 {0}",
"Write {#0} styles into the captions of {1}?": "把 {#0} 个风格写入 {1} 的描述？",
"Each first line becomes: {0} The lyrics stay.": "每个第一行会变成：{0} 歌词保持不变。",
"Write": "写入",
"{#0} captions written": "已写入 {#0} 条描述",
"drafts here by {0}": "这里的草稿出自 {0}",
"The studio’s trainer is missing {0}:": "工作室的训练器缺少 {0}：",
"Comfy-Org's YuE2 {0} weights": "Comfy-Org 的 YuE2 {0} 权重",
"the realaudio tokenizer head": "realaudio 分词器头",
"and": "和",
"AI-Toolkit is not found at": "找不到 AI-Toolkit，位置：",
": clone ostris/ai-toolkit there (or set AITK_ROOT for the lab), or train with the studio’s own trainer.": "：把 ostris/ai-toolkit 克隆到那里（或为实验室设置 AITK_ROOT），或用工作室自己的训练器训练。",
"The realaudio tokenizer is missing from": "realaudio 分词器缺失于",
"{#0} characters, about {#1} tokens.": "{#0} 个字符，约 {#1} 个令牌。",
"Style and lyrics together: about {#0} of {#1} tokens.": "风格和歌词合计：约 {#0} / {#1} 个令牌。",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "风格和歌词合计：约 {#0} / {#1} 个令牌 —— 对完整长度的歌曲和乐谱来说太长。",
"Unlike the model's training styles:": "与模型训练时的风格不同之处：",
"longer than 1,600 characters (the official examples stop at 999)": "超过 1,600 个字符（官方示例最长 999）",
"{#0} Unicode arrow (→): write -> instead": "{#0} 个 Unicode 箭头（→）：请改写成 ->",
"{#0} Unicode arrows (→): write -> instead": "{#0} 个 Unicode 箭头（→）：请改写成 ->",
"dynamics marks (never in the official styles)": "力度记号（官方风格中从不出现）",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{#0} 个“Label:”字段（110 个官方风格中有 5 个用到）",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "歌词中有 {#0} 行方括号行带“Label:”、箭头或 p/f 记号（官方示例中没有）",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "歌词中有 {#0} 行方括号行带“Label:”、箭头或 p/f 记号（官方示例中没有）",
"{#0} instruments": "{#0} 种乐器",
"{#0} heard": "听出 {#0}",
"{#0} questioned": "存疑 {#0}",
"{#0} not identified": "未识别 {#0}",
"{#0} not judged yet": "尚未判断 {#0}",
"the Librarian does not answer: no probes to play": "资料馆没有响应：没有可播放的样例",
"{#0} styles": "{#0} 种风格",
"{#0} style": "{#0} 种风格",
"what a probe gave instead of its instrument": "样例没给出所要乐器，而给出了什么",
"Nothing matches.": "没有匹配项。",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ 风格里写的名字是请求，不是承诺。▶ A 和 ▶ B 播放的是 YuE2 对它给出的声音，大约十次中有九次。",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "有些样例非常出色，A 和 B 也一致，但乐器却不是所要的：相信耳朵，而不是名字。",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "让 YuE2 演奏的内容，一次一种乐器或一种风格，两分钟的样例（最早的是一分钟），每个两个种子，A 和 B。",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "一种乐器会塑造整首曲子的风格：点名一种乐器也会改变编曲。像旧唱片那样的噼啪声或纸张沙沙声，是运气不好的种子：换一个种子重做。",
