"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "拖动：表单占宽度的 55 到 70 %；低于 55 时录音占 60 %，表单为一栏 · 双击：默认",
"the transcriber": "扒谱器",
"written from its sound by {0}": "由 {0} 从声音写出",
"written from its sound by {0}, {1}": "由 {0} 从声音写出，{1}",
"written from its sound by the transcriber (SheetSage2), now": "刚刚由扒谱器（SheetSage2）从声音写出",
