"Only the favourites (★), in the workspace you are in": "只看收藏（★），在你所在的工作区中",
"The library read again (F5 here keeps the page and the music); Ctrl+F5 reloads the page": "重新读取了库（这里按 F5 会保留页面和音乐）；Ctrl+F5 重新加载页面",
