"Delete this run for good, with its 1 picture?": "连同 1 张图片永久删除这次运行？",
"Delete this run for good, with its {#0} pictures?": "连同 {#0} 张图片永久删除这次运行？",
"Wipe out the Artist's trash: {0}, {1}?": "清空画室的回收站：{0}，{1}？",
"This cannot be undone.": "无法撤销。",
"The covers taken off the takes stay: the library's Trash (Art) has them.": "从录音上取下的封面会保留：在库的回收站（Art）中。",
