"1 picture in the trash: the library's Trash brings them back · a run with nothing left went with them": "1 张图片移到回收站：库的回收站可以还原 · 一次已空的运行也随之移走",
"{#0} pictures in the trash: the library's Trash brings them back · a run with nothing left went with them": "{#0} 张图片移到回收站：库的回收站可以还原 · 一次已空的运行也随之移走",
"The Artist draws 1 picture · seed {#0}: it waits for a card with room, then paints (Engine → GPUs says which card does what)": "画室画 1 张图 · 种子 {#0}：先等待有空间的显卡，再开画（引擎 → GPU 说明每张卡做什么）",
"The Artist draws {#0} pictures · seed {#1}: it waits for a card with room, then paints (Engine → GPUs says which card does what)": "画室画 {#0} 张图 · 种子 {#1}：先等待有空间的显卡，再开画（引擎 → GPU 说明每张卡做什么）",
