"All the sound strengths together. By ear (05.10.2026): two adapters at sound 1.0 each, 2.0 together, brought a heavy bass; 0.55 together sounded right. Green to 1, amber to 1.5, red past it. Drag it to move them all at once, each in proportion.": "所有声音强度的合计。凭耳朵（05.10.2026）：两个适配器各在声音 1.0，合计 2.0，带来了沉重的低音；合计 0.55 听起来正好。到 1 为绿，到 1.5 为琥珀，再高为红。拖动可一次移动全部，各自按比例。",
