"Tick what to look for. A take is shown when it has all of the ticked (AND), any of them (OR) or none of them (NOR); the numbers count the takes of this place.": "勾选要找的内容。录音满足全部勾选项（AND）、任一勾选项（OR）或都不满足（NOR）时显示；数字为此处的录音数。",
