"How often should the studio look for a new release?": "工作室多久检查一次新版本？",
"It asks GitHub for the list of its releases, nothing more. When one is out you are asked first; Engine → Updates can update by itself instead, and look whenever you ask.": "它只向 GitHub 询问发布列表，别无其他。有新版本时会先问你；也可以改为在 引擎 → 更新 中自动更新，并在你要求时检查。",
