"Auto for {#0} GB: context {#1}, VAE tiles {#2}": "{#0} GB 的自动设置：上下文 {#1}，VAE 分块 {#2}",
"Auto for {#0} GB: whole context, VAE tiles {#1}": "{#0} GB 的自动设置：完整上下文，VAE 分块 {#1}",
"Auto for {#0} GB: context {#1}, VAE tiles {#2}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "{#0} GB 的自动设置：上下文 {#1}，VAE 分块 {#2}；主干和是否保持模型加载由你决定。按“保存”应用。",
"Auto for {#0} GB: whole context, VAE tiles {#1}; the backbone and keeping models loaded stay your choice. Press Save to apply.": "{#0} GB 的自动设置：完整上下文，VAE 分块 {#1}；主干和是否保持模型加载由你决定。按“保存”应用。",
"{#0} of them have artwork already: drawing for the {#1} without leaves those as they are; redrawing all keeps each old picture beside its take.": "其中 {#0} 个已有封面图：只为没有的 {#1} 个画会保持那些不变；全部重画会把每张旧图保存在它的录音旁边。",
"All of them have artwork already: each old picture is kept beside its take.": "全部已有封面图：每张旧图都会保存在它的录音旁边。",
"Drawing artwork for {#0} takes, one after another: about {#1} minutes": "正在为 {#0} 个录音逐个绘制封面图：大约 {#1} 分钟",
"Artwork drawn: {#0} of {#1}": "已画封面图：{#0}/{#1}",
"Take the artwork off “{0}”?": "移除“{0}”的封面图？",
"It is kept beside the take, in artwork-removed/, and the take's MP3s lose it as their cover; the take's menu can paint a new one.": "它会保存在录音旁边的 artwork-removed/ 中，录音的 MP3 将不再以它为封面；录音的菜单可以画一张新的。",
"Take the artwork off {#0} takes?": "移除 {#0} 个录音的封面图？",
"Each picture is kept beside its take, in artwork-removed/, and their MP3s lose it as their cover; the menu can paint new ones.": "每张图都会保存在它的录音旁边的 artwork-removed/ 中，它们的 MP3 将不再以它为封面；菜单可以画新的。",
"The artwork is off {#0} takes: kept beside each, in artwork-removed/": "已移除 {#0} 个录音的封面图：分别保存在旁边的 artwork-removed/ 中",
"Each is made again from its own request with new seeds, the score and the music anew: minutes on a GPU each, {0} of music in all. They queue one after another; the old ones are kept in “Sourced for Regeneration”.": "每个都会用新种子从它自己的请求重新制作，乐谱和音乐全部重来：每个在 GPU 上要几分钟，总共 {0} 的音乐。它们依次排队；旧的保存在“重新生成的来源”中。",
"End the take at a moment": "在某一时刻结束录音",
"{0} ends at which moment (m:ss)? Its last {#1} s fade out, and nothing after it is kept. A new take; this one stays.": "{0} 在哪个时刻（m:ss）结束？最后 {#1} 秒淡出，之后的内容不保留。生成新的录音；这个保留。",
"Ending {0} at {1}…": "正在让 {0} 在 {1} 结束…",
"Fade the take in": "录音淡入",
"{0} rises from silence over how many seconds? A new take; this one stays.": "{0} 从静音中用多少秒升起？生成新的录音；这个保留。",
"Fading {0} in over {1} s…": "正在让 {0} 用 {1} 秒淡入…",
"A loop from this take": "用这段录音做循环",
"From the bar at {0} (the first: play the take and pause where the loop should begin), how many bars: 1, 2, 4 or 8? Seamless, its end running into its start; saved as a WAV.": "从 {0} 处的小节开始（第一个：播放录音，在循环应开始处暂停），多少小节：1、2、4 还是 8？无缝衔接，结尾接回开头；保存为 WAV。",
"From the bar at {0} (where the player stands), how many bars: 1, 2, 4 or 8? Seamless, its end running into its start; saved as a WAV.": "从 {0} 处的小节开始（播放器所在位置），多少小节：1、2、4 还是 8？无缝衔接，结尾接回开头；保存为 WAV。",
"The loop: {0}": "循环：{0}",
"1 bar, {#0} s at {#1} BPM, {2}": "1 小节，{#1} BPM 下 {#0} 秒，{2}",
"{#0} bars, {#1} s at {#2} BPM, {3}": "{#0} 小节，{#2} BPM 下 {#1} 秒，{3}",
"The take ends before those bars do": "录音在这些小节之前就结束了",
"Decoding {0} with the {1} VAE…": "正在用 {1} VAE 解码 {0}…",
"Rendering {0}…": "正在渲染 {0}…",
"Recite the lyrics on this score?": "在这份乐谱上朗诵歌词？",
"{#0} lines on bars {#1}–{#2} of {#3} ({4}, {#5} BPM, {6}): a syllable an eighth on a tone of each bar's chord, a breath after a comma and a full stop, the line's last syllable a quarter lower; the instruments, chords, key and tempo stay. The score and the lyrics in the form are replaced: Ctrl+Z in each box brings the old ones back.": "{#0} 行放在 {#3} 的第 {#1}–{#2} 小节（{4}，{#5} BPM，{6}）：每个音节一个八分音符，落在每小节和弦的一个音上，逗号和句号后换气，行末音节用四分音符并降低；乐器、和弦、调和速度不变。表单中的乐谱和歌词会被替换：在各输入框按 Ctrl+Z 可恢复原样。",
"{#0} lines on bars {#1}–{#2} of {#3} ({4}, {#5} BPM, {6}): a syllable a sixteenth (as rap is said: eighths left lines out) on a tone of each bar's chord, a breath after a comma and a full stop, the line's last syllable an eighth lower; the instruments, chords, key and tempo stay. The score and the lyrics in the form are replaced: Ctrl+Z in each box brings the old ones back.": "{#0} 行放在 {#3} 的第 {#1}–{#2} 小节（{4}，{#5} BPM，{6}）：每个音节一个十六分音符（像说唱那样：用八分音符会有行放不下），落在每小节和弦的一个音上，逗号和句号后换气，行末音节用八分音符并降低；乐器、和弦、调和速度不变。表单中的乐谱和歌词会被替换：在各输入框按 Ctrl+Z 可恢复原样。",
"Recited: {#0} lines on bars {#1}–{#2}; the planning mode is Full now. Generate sings them on this score": "已朗诵：{#0} 行放在第 {#1}–{#2} 小节；规划模式现在为完整。生成时会在这份乐谱上演唱",
"Recited: {#0} lines on bars {#1}–{#2}. Generate sings them on this score": "已朗诵：{#0} 行放在第 {#1}–{#2} 小节。生成时会在这份乐谱上演唱",
