"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "适用于 16 GB 的显卡（低于 20 GB 时其文本编码器在处理器上读取提示词：17 GB 内存）；在 3090 上每张约半分钟；已有一部分时会更少",
"For a card of 24 GB; less when some of it is here": "适用于 24 GB 的显卡；已有一部分时会更少",
