"Trains on unquantized weights; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "在未量化的权重上训练；其中包括 MERT-v2-FullSong 的 2.5 GB，已有时会更少",
"For a smaller card; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "适用于较小的显卡；其中包括 MERT-v2-FullSong 的 2.5 GB，已有时会更少",
