"The whole page's text smaller or larger (−2 to +4 pt): the layout stays; a lifted frame has its own on top": "整页文字变小或变大（−2 到 +4 pt）：布局不变；分离出的框在上面有自己的设置",
"Keys": "按键",
"Line numbers": "行号",
"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "像代码编辑器那样在框中显示行号（Alt+K 标记一行，Alt+J 跳到下一个标记）",
"Marks: {0}": "标记：{0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "已标记的行：Alt+K 标记或取消标记光标所在行，Alt+J 到下一个，Alt+Shift+J 到上一个，Alt+Shift+K 全部清除。按下跳到下一个。",
"Press to go to the next one.": "按下跳到下一个。",
"line {0}: {1}": "第 {0} 行：{1}",
"Tags not closed or astray: {0}": "未闭合或错位的标签：{0}",
"Round brackets to look at: {0}": "需要查看的圆括号：{0}",
"Stress marks off a vowel: {0}": "不在元音上的重音符：{0}",
"Words with two stress marks: {0}": "有两个重音符的词：{0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "重音符（U+0301）紧跟在它所重读的元音之后。按下跳到下一个。",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "一个词两个重音符：有意的，还是笔误？按下跳到下一个。",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "{0} 是带间距的重音符号，不是重音符（元音后的 U+0301）",
"at the line's start": "在行首",
"(before {0})": "（在 {0} 之前）",
"after a space": "在空格之后",
"a second mark on {0}": "{0} 上的第二个标记",
"on {0}, not a vowel": "在 {0} 上，不是元音",
"after {0}": "在 {0} 之后",
"two marks in {0}": "{0} 中有两个标记",
"Consonant beats: {0}": "辅音拍：{0}",
"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "没有元音承载的拍，与音节一起计入每行的条中（颜色较浅）：没有元音的词（с, в, к, з, й, ў），以及词内在塞擦音前闭合的塞音（глу-п-цо́в）",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "歌词编辑器的按键，与 mcedit 相同：\nAlt+K  标记光标所在行（再按：取消标记）\nAlt+J  下一个标记 · Alt+Shift+J 上一个\nAlt+O  清除标记（Alt+Shift+K 也可）\nAlt+L  按行号跳转\nCtrl+Y  删除该行\nAlt+↑ Alt+↓  移动该行或所选的行\n行首的 [ 或 Ctrl+Space  段落标签\nCtrl+F  在框中查找\nAlt+I  乐器和风格速查表\nCtrl+Z  撤销一次修改",
"Already in the lyrics, line {0}: a song has one": "歌词第 {0} 行已经有了：一首歌只有一个",
"The lyrics number their verses: this is the next one": "歌词给主歌编号：这是下一段",
"{0} times in the 110 official examples": "在 110 个官方示例中出现 {0} 次",
"{#0} times in the 110 official examples": "在 110 个官方示例中出现 {#0} 次",
"already at line {0}": "已在第 {0} 行",
"the next verse": "下一段主歌",
"↑ ↓ choose · Enter or Tab puts it in · Esc closes": "↑ ↓ 选择 · Enter 或 Tab 插入 · Esc 关闭",
"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "测试：110 个官方示例都没有写它，所以 YuE2 可能会把它当歌词唱出来或跳过。保留前先听一听。",
