"Male vocals in the Style: a click puts them there (in place of female ones); a click on the lit one takes their tag out": "风格中的男声：点击放入（替换女声）；点击已亮起的会去掉它的标签",
"Female vocals in the Style: a click puts them there (in place of male ones); a click on the lit one takes their tag out": "风格中的女声：点击放入（替换男声）；点击已亮起的会去掉它的标签",
