"Sound seed {#0}\nsame music, another grain": "声音种子 {#0}\n同样的音乐，不同的颗粒",
"None on this server. Start it with --sliders to add voice and genre sliders.": "这台服务器上没有。用 --sliders 启动以添加嗓音和流派滑块。",
"{#0} decoders · {1} picked in the ☰ menu · a finished song can add another from its page": "{#0} 个解码器 · 在 ☰ 菜单中选择了 {1} · 完成的歌曲可以在其页面上再添加一个",
