"Lay the lyrics on this score…": "把歌词放到这份乐谱上…",
"Between the sections a vocalise an octave up, written into the lyrics as «(Ooh, aah)», instead of a bar's rest": "段落之间用高八度的元音吟唱代替一个小节的休止，在歌词中写作“(Ooh, aah)”",
"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "把手头的录音带出工作室：混好的音轨原样导出，或把整段录音导入你的 DAW（如果已在这里分轨，则带上分轨）",
"{#0} checked: a line with a number acts on all of them": "已勾选 {#0} 个：带数字的行对全部生效",
"Text profiles make a pasted text ready to read: pick a Speech profile in Profile to use them": "文本配置会把粘贴的文本整理成可朗读的样子：在“配置”中选择一个语音配置即可使用",
