"End at…": "结束于…",
"End the take at a moment: its last 2 s fade out, and nothing after it is kept. For a song that runs on past its proper end (in Full, the score's leftover bars after the last words). The moment is where the player stands when this take plays; otherwise you are asked. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "在某一时刻结束录音：最后 2 秒淡出，之后的内容不保留。适用于超过应有结尾还在继续的歌曲（在完整规划中，即最后歌词之后乐谱剩下的小节）。时刻为这段录音播放时播放器所在的位置；否则会询问你。用录音保存的潜在表示几秒完成（就是原来的声音），否则重新渲染它的音乐代码。生成新的录音；这个保留。",
"Fade in…": "淡入…",
"Fade the take in: its first seconds rise from silence (2 s unless you say otherwise), for a song that starts too abruptly. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "录音淡入：开头几秒从静音中升起（默认 2 秒，除非你另行指定），适用于开头太突兀的歌曲。用录音保存的潜在表示几秒完成（就是原来的声音），否则重新渲染它的音乐代码。生成新的录音；这个保留。",
"Loop…": "循环…",
"A loop from this take: 1, 2, 4 or 8 bars on its score's bar lines, from the bar where the player stands (else the first), seamless (its end runs into its start), saved as a WAV named with its tempo and key": "用这段录音做循环：沿乐谱的小节线取 1、2、4 或 8 小节，从播放器所在的小节开始（否则从第一小节），无缝衔接（结尾接回开头），保存为以速度和调命名的 WAV",
"On 15 s": "前进 15 秒",
"Back 15 s": "后退 15 秒",
"On to the next quarter-minute mark. The → key: to the next 5 s mark": "到下一个 15 秒刻度。→ 键：到下一个 5 秒刻度",
"A sound when a run ends": "运行结束时的提示音",
"A sound when a run made here ends: two notes up when it is done (a queue of runs once, when its last one ends), two down when one fails. None over a new song that starts playing by itself; as loud as the player. Click to make none.": "在这里发起的运行结束时的提示音：完成时两个上行音（一串运行只在最后一个结束时响一次），失败时两个下行音。自动开始播放的新歌上不叠加；音量与播放器相同。点击可关闭。",
"Count again": "重新统计",
"Count the folders' files and sizes again": "重新统计文件夹的文件数和大小",
"Scan the machine": "扫描机器",
"What this machine has, and what suits it: the backbone, the context and the VAE tiles, the painter": "这台机器有什么，以及适合它的：主干、上下文和 VAE 分块、画师",
"Check again": "再次检查",
"Compare what is here with the pinned lists again; nothing is downloaded": "把这里已有的与固定的列表再比对一次；不下载任何内容",
"Restart the engine": "重启引擎",
"The engine reads its backbones and decoders when it starts": "引擎在启动时读取它的主干和解码器",
"Folders": "文件夹",
"What the studio downloads beside itself: the decoders, Whisper, the stems' models, UniverSR and the LoRAs, which the install brings, and the extras you ask for. Each file comes from Hugging Face at the revision the release pins and is checked against its size; a download cut short goes on where it stopped. Nothing is downloaded until you press Fetch.": "工作室在自身旁边下载的内容：解码器、Whisper、分轨模型、UniverSR 和 LoRA（安装会带来这些），以及你要求的额外内容。每个文件都按版本固定的修订从 Hugging Face 下载，并按大小校验；中断的下载会从停下的地方继续。在你按“下载”之前不会下载任何内容。",
"Where your work lives: the songs (with the workspaces fetched from Hugging Face), the trash, the Artist's pictures and the Writer's documents. Each may live on any disk: the studio's folder then holds a link to it, and everything reads it there as before. The models, the LoRAs and the training sets keep their places.": "你的作品存放的位置：歌曲（含从 Hugging Face 下载的工作区）、回收站、画室的图片和写作室的文档。每一项都可以放在任意磁盘上：此时工作室的文件夹里存放指向它的链接，一切照旧从那里读取。模型、LoRA 和训练集位置不变。",
"VRAM limit": "显存上限",
"{0} GB used · training {1}": "已用 {0} GB · 训练 {1}",
"{0} GB · 1 module": "{0} GB · 1 个模块",
"supplied": "已提供",
"F32 (option since removed)": "F32（此选项已移除）",
"not started with one": "启动时未指定",
