"V move · B brush · E eraser · H or Space the board · [ ] the brush · wheel zoom · Alt+wheel the picture's size · F in sight · 1 2 3 the shapes · Ctrl+Z": "V 移动 · B 画笔 · E 橡皮 · H 或空格 移动画板 · [ ] 画笔大小 · 滚轮 缩放 · Alt+滚轮 图片大小 · F 进入视野 · 1 2 3 画幅 · Ctrl+Z",
