"The painters, the Qwen fine-tunes and the adapters the studio can fetch for the Artist, each with its size, here or not: from the studio's models repository and from their makers": "工作室可以为画室下载的画师、Qwen 微调和适配器，各附大小，以及是否已有：来自工作室的模型仓库和它们的作者",
"Painters and adapters to fetch": "要下载的画师和适配器",
