"Artist's adapters": "画室的适配器",
"the fp8 fine-tunes of Qwen-Image 2512 for finished realism (a card of 24 GB), from {0}, shared there by their authors' leave (Civitai: share and sell)": "Qwen-Image 2512 的 fp8 微调，追求成品级写实（需 24 GB 的显卡），来自 {0}，经作者许可在那里共享（Civitai：可分享和出售）",
"and Qwen-Image 2512's parts (17.7 GB) when they are not here": "以及不在这里时 Qwen-Image 2512 的部件（17.7 GB）",
