"Keep the canvas and draw the shapes picked in the form (Ctrl+Enter)": "保留画布并绘制表单中选中的画幅（Ctrl+Enter）",
"Its trigger words into the prompt:": "把它的触发词放入提示：",
"Its trigger words out of the prompt:": "把它的触发词移出提示：",
