"Made for {0}: it reaches none of this painter's layers": "为 {0} 制作：它触及不到这个画师的任何层",
"Eight adapters at most in the list: take one off first": "列表中最多八个适配器：先去掉一个",
"Four in the run at most: this one came in muted (right-click: mute another and bring it in)": "一次运行最多四个：这个以静音状态加入（右键：静音另一个并把它加入）",
