"When an adapter comes into the run its trigger words are added to the prompt, and taken out when it leaves": "适配器加入运行时，其触发词会加到提示中，离开时会被移除",
"Its SHA-256 alone goes to civitai.com: its name, base model and trigger words come back": "只把它的 SHA-256 发送到 civitai.com：返回名称、基础模型和触发词",
