"Passes": "分遍",
"Each pass runs its model over the picture as it stands and lands at the picture's own size × its factor (each factor the picture's, not the pass before's): Viktor's ComfyUI stack, CR Apply Multi Upscale. Then the long side, then the colours put back to the picture's.": "每一遍都在当前图片上运行它的模型，落到原图尺寸 × 它的倍数（倍数总是相对原图，而不是相对上一遍）：Viktor 的 ComfyUI 堆栈，CR Apply Multi Upscale。然后是长边，最后把颜色还原为原图的颜色。",
"Viktor's Qwen 2512 chain (ComfyUI)": "Viktor 的 Qwen 2512 链（ComfyUI）",
