"“{0}” has this picture as its cover: take it off the take too, or leave it? The take keeps a copy of its own.": "“{0}”用这张图片作封面：也从录音上取下，还是保留？录音保有自己的副本。",
"{#0} takes have these pictures as their covers: take the covers off them too, or leave them? Each take keeps a copy of its own.": "{#0} 段录音用这些图片作封面：也取下它们的封面，还是保留？每段录音都保有自己的副本。",
