"Spectrum over the wave": "波形上的频谱",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "波形上的频谱：指针放在波形上时，整段录音的频谱图会出现在播放器上方，与波形同宽，上面是该段落的歌词。点击可关闭。",
"The take's spectrum": "录音的频谱",
"spectral centroid": "频谱质心",
"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "频谱质心：每一刻声音的重心所在，即它的明亮度；越高越亮",
"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS：每一刻的响度，单位 dBFS，显示在底部的条带中；虚线是这段录音自身的平均值",
"Frequency scale": "频率刻度",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "对数刻度的频率，与耳朵的听感一致：每个八度一样高",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "线性刻度的频率：高频宽，低频挤在底部",
"The mean power of each band over the whole take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k": "整段录音中每个频段的平均功率（Welch，dB）：SUB 20–80 Hz、LOW 80–300、MID 300–2k、HI-MID 2–6k、HIGH 6–12k、AIR 12–20k",
