"its painter said nothing for {#0} minutes: stopped": "画师 {#0} 分钟没有任何输出：已停止",
"its painter said nothing for {#0} s: stopped": "画师 {#0} 秒没有任何输出：已停止",
"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "第二遍，与 Viktor 的 ComfyUI 工作流相同：把图片放大 1.5 或 2 倍，用它自己的画师、适配器、提示词和种子重新绘制，步数和采样器取自表单；独立的一次运行",
"Second pass…": "第二遍…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "第二遍可以把图片改变多少：0.3 保留画面并添加细节，0.5 打磨质感，0.7 重画形体",
"Second pass asked:": "已请求第二遍：",
"The second pass ×{0} waits for a card with room, then paints the picture over": "第二遍 ×{0} 正在等待有空间的显卡，然后重新绘制图片",
