"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "在从图片开始绘制之前给它加上新的噪声，与 Viktor 的 ComfyUI 工作流（InjectLatentNoise）相同：0 不加，0.3 带来新的颗粒和细节，0.6 是他的第二遍，超过 1 图片的形体开始瓦解",
"extra noise {0}": "附加噪声 {0}",
