"for its style only (Qwen-Image 2.1)": "只取它的风格（Qwen-Image 2.1）",
"How the picture is used: painted from (image to image, by the form's painter, as far as How much it may change says); edited by the prompt's words (Qwen-Image 2.1 keeps the scene and changes what the words say); or for its style only (Qwen-Image 2.1 paints the prompt's own scene in the picture's technique, brushwork, palette and light). Qwen-Image 2.1 is under the Qwen Research Licence: research and evaluation only": "图片的用法：从它开始绘制（图生图，用表单中的画师，程度由“允许改变多少”决定）；用提示词的文字编辑（Qwen-Image 2.1 保留场景，只改文字所说的部分）；或只取它的风格（Qwen-Image 2.1 用图片的技法、笔触、配色和光线画出提示词的场景）。Qwen-Image 2.1 采用 Qwen Research Licence：仅限研究和评估",
"in the picture's style": "沿用图片风格",
"edited by words": "用文字编辑",
"The answer reached the output limit: review it carefully, or raise Max tokens.": "回答已达到输出上限：请仔细检查，或调高“最大 token 数”。",
"The model gave an empty answer: nothing came back from {0}.": "模型给出了空回答：{0} 没有返回任何内容。",
"It may have spent the whole answer on its thinking, or stopped at once. Send it again, raise Max tokens, or pick another model.": "它可能把整个回答都用在了思考上，或者立刻就停止了。请再发送一次、调高“最大 token 数”，或换一个模型。",
"The writer failed: {0}": "写作室失败了：{0}",
"Lettering": "题字",
"About the lettering": "关于题字",
"A title, and a second line under it, lettered as part of the painting, not laid over it: Qwen-Image paints them with the picture, or Qwen-Image 2.1 letters a finished one, the reference. Each picture is read back by the listener (Qwen2.5-Omni) and one misspelled is painted again with another seed, up to three times; one still misspelled is said so, with what it reads": "标题及其下方的第二行，作为画面的一部分写进去，而不是叠在上面：Qwen-Image 与画面一起绘制，或由 Qwen-Image 2.1 在完成的画（参考图）上题写。每幅画都由听者（Qwen2.5-Omni）回读，拼错的会换一个种子重画，最多三次；仍有错误时会如实说明，并给出读到的文字",
"The words to letter, exactly as they are to be spelled": "要题写的文字，按应有的写法准确填写",
"The take's title": "样本的标题",
