"Second line": "第二行",
"Smaller, under the title: the artist, the album; empty for none": "标题下方的小字：艺人、专辑；留空则不写",
"The letters": "字体",
"large elegant classical serif capitals in warm gold, with even letter spacing": "大号典雅的古典衬线大写字母，暖金色，字距均匀",
"What the letters look like, in words: the kind of letters, their colour, how they sit; empty: classical serif capitals in warm gold": "用文字描述字体：字的类型、颜色、排布；留空则为暖金色古典衬线大写",
"At the top": "顶部",
"In the middle": "中间",
