"How": "方式",
"Painted with the picture: Qwen-Image 2512 or 2.1 paints the prompt's scene and the letters in it. On the reference: Qwen-Image 2.1 letters the reference picture by words and keeps the rest": "随画面绘制：Qwen-Image 2512 或 2.1 绘制提示词的场景及其中的文字。在参考图上：Qwen-Image 2.1 按文字在参考图上题写，其余保持不变",
"painted with the picture": "随画面绘制",
"on the reference picture (Qwen-Image 2.1)": "在参考图上 (Qwen-Image 2.1)",
"Lettering a finished picture is Qwen-Image 2.1's: it is not on this machine": "在完成的画上题字需要 Qwen-Image 2.1，而本机上没有它",
"On the reference picture: take one with «As reference» first": "在参考图上：请先用“作为参考”选一幅画",
"Lettering is Qwen-Image's: choose Qwen-Image 2512 or 2.1 as the painter": "题字由 Qwen-Image 完成：请选择 Qwen-Image 2512 或 2.1 作为画师",
"Lettering on this picture: write its title, then Draw (Qwen-Image 2.1 letters it and keeps the rest)": "在这幅画上题字：写下标题，然后点“绘制”（Qwen-Image 2.1 题写，其余保持不变）",
"Spelled as asked: the listener reads it so": "拼写与要求一致：听者读出的正是这样",
"Misspelled in every try: it reads": "每次尝试都有拼写错误：读到的是",
"tries": "次尝试",
"lettered": "题字",
"misspelled: it reads": "有拼写错误：读到的是",
"Letter this picture: the title and second line of the form's Lettering, by Qwen-Image 2.1, the rest kept": "在这幅画上题字：用表单“题字”中的标题和第二行，由 Qwen-Image 2.1 完成，其余保持不变",
"Letter it": "题字",
"Not read back:": "未回读：",
"Where in the frame the lettering stands: across its upper part, its middle or its lower part": "题字在画面中的位置：上部、中间或下部",
"Lyrics guidance": "歌词引导",
"as Guidance": "同引导",
"The lyrics' own guidance in the music stage: how hard the words are followed, apart from the style's pull, which Guidance keeps. Empty: the same as Guidance, as before. Viktor's measure: the lyrics below 2.6, while the music holds up to 4. A scale of its own adds a third branch, the prompt without its lyrics: a little more memory, about the same time": "音乐阶段中歌词专用的引导：在风格的牵引（由引导掌握）之外，单独决定歌词被遵循的力度。留空：与引导相同，与以前一样。维克多的经验：歌词低于 2.6，而音乐到 4 都稳定。单独的数值会增加第三条分支（不含歌词的提示词）：内存略多，时间几乎相同",
"Viktor's measure: the lyrics hold below 2.6 while the music goes up to 4. Empty: the same as Guidance.": "维克多的经验：歌词保持在 2.6 以下，音乐可到 4。留空：与 CFG 相同。",
"Lyrics guidance from 2.6 is an experiment": "歌词 CFG 从 2.6 起属于实验",
"Viktor's measure: the lyrics hold below 2.6, while the music (Guidance) is stable up to 4.": "维克多的经验：歌词保持在 2.6 以下，而音乐（CFG）到 4 都稳定。",
"Lyrics guidance must be a number, 0 or more": "歌词引导必须是 0 或更大的数字",
"Repetition": "重复",
"Tokens": "Token",
"Time": "时间",
"Seconds of music": "音乐秒数",
"Length cap": "时长上限",
"Sound stage": "声音阶段",
"Decoder": "解码器",
"Whole run": "整次运行",
"Realtime": "实时倍数",
"Versions × variations": "版本 × 变体",
"Score guard": "乐谱守卫",
"Free tempo": "自由速度",
"Free tempo: the music is made from the score without its tempo marks (Q:), so the voice and the beat breathe on their own: rubato, non-linear. The score in the form keeps them; Direct has no score to free. On by itself when the Style asks for rubato or non-linear and names no BPM.": "自由速度：用去掉速度标记（Q:）的乐谱来生成音乐，人声和节拍会自己呼吸：自由速度（rubato）、非线性。表单里的乐谱保留这些标记；Direct 模式没有乐谱。当风格要求 rubato 或 non-linear 且没写 BPM 时会自动开启。",
"Want non-linearity or rubato? Remove the BPM from your style!": "想要非线性或 rubato？把 BPM 从你的风格里删掉！",
"Free tempo on: your Style asks for rubato or non-linear, so the music is made without the score's tempo": "已开启自由速度：你的风格要求 rubato 或非线性，音乐将不按乐谱的速度生成",
"The run": "运行",
"no score": "无乐谱",
"Within Viktor's range for the music, 1.0 to 4.0: 4.0 the brightest, 3.0 just as bright, 1.6 the studio's own": "在维克多的音乐范围内（1.0 到 4.0）：4.0 最明亮，3.0 几乎一样，1.6 是工作室默认",
"Past 4.0: brighter still, and the music may begin to break; listen before you keep it": "超过 4.0：更明亮，但音乐可能开始破裂；保留前先听听",
"Far past Viktor's range for the music (1.0 to 4.0): expect a broken take": "远超维克多的音乐范围（1.0–4.0）：预计会得到破损的样本",
"Within Viktor's range for the lyrics, 1.0 to 2.6: 2.2 holds the words with the music at 4.0; at 1.6 they dissolve, velvety": "在维克多的歌词范围内（1.0 到 2.6）：音乐为 4.0 时 2.2 能保住歌词；在 1.6 时歌词如天鹅绒般融化",
"Past 2.6: the words begin to burn": "超过 2.6：歌词开始被烧焦",
"Far past 2.6: burnt words": "远超 2.6：歌词被烧焦",
"The lyrics follow Guidance here: past 2.6 they begin to burn; give them their own Lyrics guidance (2.2 holds them with the music at 4.0)": "此处歌词跟随引导：超过 2.6 会开始被烧焦；请给它单独的歌词引导（音乐为 4.0 时 2.2 能保住）",
"Viktor's range: the music 1.0 to 4.0; past it the light beside the field turns amber, then red": "维克多的范围：音乐 1.0 到 4.0；超出后字段旁的灯变为琥珀色，再变红",
"Viktor's range: the lyrics 1.0 to 2.6; past it the light beside the field turns amber, then red. Empty: the same as Guidance": "维克多的范围：歌词 1.0 到 2.6；超出后灯变为琥珀色，再变红。留空：同引导",
"The two guidances should differ: by 0.1 at the least, by 0.4 to 1.0 at best (Viktor's ear); equal, half the lyrics drift into hallucination, and the vowels lose their stress": "两个引导应当拉开：至少相差 0.1，最好相差 0.4 到 1.0（维克多的耳朵）；相等时一半歌词会滑向幻听，元音也会失去重音",
"Sections to sing anew": "要重唱的段落",
"Hide disliked": "隐藏不喜欢的",
"the ☰ menu's own: the decoder for the songs to come": "与 ☰ 菜单相同：之后歌曲的解码器",
