"Shift and keys together: a chord on the cursor's bar": "Shift 与琴键同时按：在光标所在小节写和弦",
"The computer's keys: A S D F G H J K L ; ' white, W E T Y U O P ] black · Z X an octave": "电脑按键：A S D F G H J K L ; ' 为白键，W E T Y U O P ] 为黑键 · Z X 换八度",
"← → a semitone · ↑ ↓ a step · Tab: the other staff": "← → 半音 · ↑ ↓ 一步 · Tab：另一个谱表",
