"The instruments are on their way…": "乐器正在加载…",
"MIDI needs the studio opened as localhost or over https; this page is {0}. From another computer: ssh -L {1} {2}, then {3}": "浏览器只在 localhost 或 https 页面上提供 MIDI；本页面是 {0}。从另一台电脑：ssh -L {1} {2}，然后打开 {3}",
"{0} control port(s) left to the controls": "控制端口留给控制器：{0}",
