"A MIDI keyboard of this computer: its keys play here; with Rec on, a key writes a note at the cursor and the cursor steps on": "这台电脑的 MIDI 键盘：它的琴键在这里发声；开启 Rec 时，按键会在光标处写入一个音，光标随之前进",
"Rec: a key (of the MIDI keyboard, the computer's keys or the keys below) writes a note of the grid's length at the cursor into the staff in hand, and the cursor steps on": "Rec：按键（MIDI 键盘、电脑按键或下方画出的琴键）在光标处向手上的谱表写入一个网格长度的音，光标随之前进",
"Rec": "Rec",
"The roll into the score in the box: only the lines whose notes or chords changed are written anew, every other line stays as YuE2 wrote it": "把卷帘写入输入框的乐谱：只重写音符或和弦有变化的行，其余各行保持 YuE2 写的样子",
"As YuE2 wrote it": "YuE2 写的样子",
"As it stands now": "现在的样子",
"Click: a note · drag: move, its lower edge: longer · right-click or Delete: away · Shift and keys together: a chord on the cursor's bar · keys A S D F G H J K L ; ' and W E T Y U O P ]: a keyboard and a half, Z X an octave · ←→ a semitone, ↑↓ a step · Tab: the other staff · wheel: time, Ctrl+wheel: closer · F11: the whole screen": "单击：放一个音 · 拖动：移动，拖下边缘：拉长 · 右键或 Delete：删除 · Shift 与琴键同时按：在光标所在小节写和弦 · 按键 A S D F G H J K L ; ' 与 W E T Y U O P ]：一个半八度，Z X 换八度 · ←→ 半音，↑↓ 一步 · Tab：另一个谱表 · 滚轮：时间，Ctrl+滚轮：放大 · F11：全屏",
