"The score in the box as a piano roll: both staves, Vocal and Ins, a note a click; written back into the score line by line, every untouched line as YuE2 wrote it": "把输入框中的乐谱作为钢琴卷帘：Vocal 和 Ins 两个谱表，单击一个音；逐行写回乐谱，未改动的行保持 YuE2 写的样子",
"No score in the box yet: load one, plan one in Full, or import a MIDI file first": "输入框中还没有乐谱：载入一份、在 Full 中规划一份，或导入一个 MIDI",
"The score does not read, so the roll cannot open it:": "乐谱无法读取，所以卷帘无法打开它：",
"The staff in hand": "手上的谱表",
"The vocal staff in hand: what is sung. Ins stays drawn faint behind it": "手上是人声谱表：唱的内容。Ins 在后面淡淡显示",
"The instruments' staff in hand: their melody. Vocal stays drawn faint behind it": "手上是乐器谱表：它们的旋律。Vocal 在后面淡淡显示",
