"Both staves from the cursor, as plain tones at the score's tempo (Space); a click on the ruler sets the cursor": "从光标起以乐谱速度用简单音色播放两个谱表（空格）；单击标尺设置光标",
"The roll into the score in the box: only the lines whose notes changed are written anew, every other line stays as YuE2 wrote it": "把卷帘写入输入框的乐谱：只重写音符有变化的行，其余各行保持 YuE2 写的样子",
