"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "来自任何地方的音轨（WAV、FLAC、MP3…）作为录音进入资料库，并标记为导入；从这里连出的路线会在之后的每次导入上自动运行",
"Every file made from this take, each under the one it came from: play, compare, rate, delete": "由这个录音生成的每个文件，排在它的来源下面：播放、比较、评价、删除",
"The spectrum of the take or of a file made from it: how loud each band is, over time": "录音或其生成文件的频谱：每个频段随时间有多响",
"Faults measured in a file: clicks, clipping, the frame buzz, a hum": "在文件中测得的问题：咔嗒声、削波、帧嗡声、哼声",
"The lyrics held against what is sung (Whisper): which lines came and which did not": "歌词与实际演唱的对照（Whisper）：哪些行唱到了，哪些没有",
"The frame buzz of YuE2's sound out of the take: needed for every YuE2 take, off for a track from elsewhere": "把 YuE2 声音的帧嗡声从录音中去掉：每个 YuE2 录音都需要，外来音轨关闭",
"UniverSR redraws the top of the spectrum above a cutoff, the original kept below it": "UniverSR 重新绘制截止频率以上的高频，以下保留原样",
"The file split into stems: four, six, eight, or the voice and the rest": "把文件分离成分轨：四、六、八条，或人声与其余",
"The stems on lanes: levels, versions, buses and automation, then a mix": "轨道上的分轨：电平、版本、总线和自动化，然后混音",
"The Digital Gateway: tape, console and tube in numbers, on a file or a mix": "数字网关：以数字模拟的磁带、调音台和电子管，用于文件或混音",
"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "Debunker：把文件或一组分轨平衡、压缩、调色并达到目标响度",
