"Letters other than Latin in the Style: {0}. YuE2 reads the style as English tags: write it in Latin letters.": "风格中有非拉丁字母：{0}。YuE2 把风格当作英文标签读取：请用拉丁字母书写。",
"Style suggestions: the Writer's model reads the Style, the Title and the lyrics whole and offers short tags this song has not got yet; a click on one puts it in (before the BPM at its end)": "风格建议：写作室的模型读取风格、标题和全部歌词，给出这首歌还没有的简短标签；点击一个即可插入（放在末尾的 BPM 之前）",
