"A 1 kHz tone at −20 dBFS out through the output and back from the input: did it come back, its gain, the noise before it, its THD": "1 kHz、−20 dBFS 的测试音从输出出去、从输入回来：是否回来、增益、之前的噪声、THD",
"Loop test": "回路测试",
