"The loop did not run: {0}": "回路未能运行：{0}",
"The setup as it is now (the steps' settings and where the nodes stand, never a take's sources) under a name": "当前的设置（各步骤的设置和节点的位置，从不包含录音的来源）以一个名字保存",
"Set every step as it was kept under this name": "按照这个名字下保存的样子设置每一步",
