"A second node of this step with its own settings, beside it: its window holds them, and a run from there runs with them": "这个步骤的第二个节点，带着自己的设置放在旁边：它的窗口保存这些设置，从那里运行就用这些设置",
"its own settings": "自己的设置",
"{0} cloned: its window holds its own settings": "已克隆{0}：它的窗口保存自己的设置",
"Delete the clone «{0}»? Its settings go with it.": "删除克隆「{0}」？它的设置会一起删除。",
"Eight clones of one step are enough": "一个步骤最多八个克隆",
"Every Generate keeps this title's style, lyrics and score apart from the takes: its versions, a diff of two, one back into the form": "每次 Generate 都会把这个标题的风格、歌词和乐谱与录音分开保存：它的版本、两版的差异、把某一版放回表单",
"Every Generate's words, kept under their title apart from the takes: a take deleted never takes them along": "每次 Generate 的文字，按标题与录音分开保存：删除录音也不会带走这些文字",
"Creator's versions": "创作室的版本",
"The Creator's version was not kept: {0}": "未能保存创作室的版本：{0}",
"The Creator's versions did not come: {0}": "未能取得创作室的版本：{0}",
"too long to compare line by line": "太长，无法逐行比较",
"the same": "相同",
"unchanged lines: {0}": "未改动的行：{0}",
"a click picks a version; Ctrl or Shift and a click, a second: their difference": "单击选择一个版本；按住 Ctrl 或 Shift 再单击选第二个：显示两者差异",
"versions: {0}": "版本：{0}",
"lines: {0}": "行：{0}",
"score": "乐谱",
"takes: {0}": "录音：{0}",
"Nothing kept under this title yet: every Generate keeps its words here.": "这个标题下还没有保存任何内容：每次 Generate 都会在这里保存它的文字。",
"Trash ({0})": "回收站（{0}）",
