"music the model writes": "模型写的音乐",
"Insert an interlude": "插入间奏",
"How long a passage after {0}? The model writes it at its own length near this, and the cut lies where its voice comes back.": "{0} 之后的间奏要多长？模型会在这附近按自己的长度写出它，切点落在它的人声回来的地方。",
"How does {0} come back?": "{0} 怎样回来？",
"About 5 seconds": "约 5 秒",
"a short bridge": "一段短桥",
"About 7 seconds": "约 7 秒",
"time to turn the mood": "转换情绪的时间",
"About 10 seconds": "约 10 秒",
"a passage of its own": "一段独立的过门",
"Straight on": "直接接上",
"its lines again at once": "它的歌词立刻再来一遍",
"After a breath": "换一口气后",
"about 4 s of music first": "先约 4 秒音乐",
"After a short interlude": "一段短间奏后",
"about 7 s of music first": "先约 7 秒音乐",
"After {0} ({1}–{2}) the model writes about {#3} s of music on the take's music seed + 1, going on from its end; the take's own next section comes in where the model's voice would. Two versions take the seeds + 1 and + 2. New takes; this one stays.": "在 {0}（{1}–{2}）之后，模型用这条录音的音乐种子 + 1 从它的结尾接着写约 {3} 秒音乐；录音自己的下一段在模型人声本该进来的地方进来。两个版本使用种子 + 1 和 + 2。生成新的录音；这个保留。",
"{0} ({1}–{2}) is sung once more after about {#3} s of music: the model goes on from its end with music first, then its lines again, on the take's music seed + 1, so the repeat is a variation, not a copy; the copy ends where the voice rests after them, and the rest of the take follows. Two versions take the seeds + 1 and + 2. New takes; this one stays.": "{0}（{1}–{2}）在约 {3} 秒音乐之后再唱一遍：模型用这条录音的音乐种子 + 1 从它的结尾先接音乐，再接同样的歌词，所以重复是变奏，不是复制；副本在其后人声停歇处结束，录音的其余部分随后接上。两个版本使用种子 + 1 和 + 2。生成新的录音；这个保留。",
"Interlude asked: its versions come as takes of their own, children of this one": "已请求间奏：各版本作为这条录音的子录音各自到来",
"No interlude can go after this section: its lines were not heard clearly": "这个段落之后无法插入间奏：它的歌词没有听清",
// HERESY 1718: one line sung anew
"Re-sing this line…": "重唱这一行…",
"Re-sing a line": "重唱一行",
"{0}, line {#1} ({2}–{3}): its words as the lyrics have them. Change them, or keep them and let only the music be new; the rest of the take stays as it is.": "{0}，第 {1} 行（{2}–{3}）：歌词里写的字。改掉它们，或者保留，只让音乐是新的；录音的其余部分保持原样。",
"{0}, line {#1} ({2}–{3}) is sung anew on a new music seed, cut halfway to the lines around it; the rest of the take stays as it is. Two versions take two seeds. New takes; this one stays.": "{0}，第 {1} 行（{2}–{3}）用新的音乐种子重唱，切点在与相邻行的中间；录音的其余部分保持原样。两个版本使用两个种子。生成新的录音；这个保留。",
"This line is under two seconds: replace its section instead": "这一行不到两秒：请替换它所在的段落",
"This line cannot be sung anew: it was not heard clearly": "这一行无法重唱：没有听清",
"The line is empty": "这一行是空的",
"More syllables than the line held: the model sings them faster, or runs over the cut": "音节比原行多：模型会唱得更快，或越过切点",
"Fewer syllables than the line held: the model may stretch them or leave a rest": "音节比原行少：模型可能拉长它们或留下停顿",
// HERESY 1719: Match sections
"Match sections": "匹配段落",
"Match sections: Whisper hears where each block of your lyrics begins in this recording, and each block takes the tag of the score section it is sung in (the score transcribed from this recording, its sections named). Words never change; you see the proposal before it goes into the form. After timoncool's YuE2-Studio and HOT-Step's Cover Studio": "匹配段落：Whisper 在这段录音里听出你歌词每一块的开头，每一块获得它所唱在的乐谱段落的标签（从这段录音转写出的、段落有名字的乐谱）。歌词文字不变；放进表单之前你会先看到建议。参照 timoncool 的 YuE2-Studio 和 HOT-Step 的 Cover Studio",
"Write or paste the lyrics first": "请先写下或粘贴歌词",
"The score has no named sections: transcribe the recording first": "乐谱没有命名的段落：请先转写这段录音",
"Whisper is listening to the recording…": "Whisper 正在听这段录音…",
"Whisper heard too little of these lyrics in the recording ({#0} %): nothing matched": "Whisper 在录音里只听出很少的歌词（{0} %）：没有匹配",
"The lyrics already match the score's sections": "歌词已经跟随乐谱的段落",
"Each block of the lyrics takes the tag of the score section it is sung in, by where Whisper heard its first line: {#0} kept, {#1} retagged, {#2} joined to the block before, {#3} unsure (left as they were); {#4} sections added (an instrumental, or a chorus written once and sung again). Words never change. Apply puts these lyrics into the form; what it holds now is kept as a version.": "歌词的每一块按 Whisper 听到它第一行的位置，获得它所唱在的乐谱段落的标签：保留 {0} 块，改标签 {1} 块，并入前一块 {2} 块，不确定 {3} 块（保持原样）；添加 {4} 个段落（器乐段，或写一次又再唱的副歌）。文字不变。「应用」把这份歌词放进表单；表单现在的内容保存为一个版本。",
"The lyrics now follow the score's sections; the old ones are kept as a version": "歌词现在跟随乐谱的段落；原来的已保存为版本",
