"A take's time on its card and wherever it is shown: how long ago, or its exact date and time. A click on a card's time flips it to the other for that take; its tip always says the other": "录音在卡片上及其他显示处的时间：多久以前，或确切的日期和时间。点击卡片上的时间可为该录音切换到另一种；提示里总是显示另一种",
"How long ago": "多久以前",
"The exact time": "确切时间",
// HERESY 1722: the crossfade, the next take whole
"Crossfade: with Play on (or Repeat all) the next take comes in whole, at its own level, as soon as this one goes quiet after its last loud moment, at most 2 to 8 s before its end; only this one's quiet tail fades under it. ⋈ 0 plays them one after another, as before. A take shorter than twice the crossfade plays whole; Repeat one never crosses.": "交叉淡化：连续播放（或全部重复）时，这条录音在最后一个响亮处之后安静下来时（最多在结尾前 2 到 8 秒），下一条以自己的音量完整进入；在它下面只有这条的安静尾巴淡出。⋈ 0 照旧一条接一条播放。短于两倍交叉淡化的录音完整播放；单曲重复从不交叉。",
