// HERESY 1736: the Trainer's held-out best
"held-out best": "留出集最佳",
"The sound half's loss on {#0} tracks it never trains on, measured at each save: the lowest so far, and the epoch it came at": "声音部分在 {0} 首从不用于训练的曲目上的损失，每次保存时测量：目前最低值及其出现的轮次",
