"The playlist's crossfade": "播放列表的交叉淡化",
// HERESY 1738: the Refiner's Mono Maker, Peak glue and True-peak ceiling
"Mono Maker": "低频单声道",
"Peak glue": "峰值粘合",
"True-peak ceiling": "真峰值上限",
"the lows in the middle": "低频居中",
"the loud moments shaved, the loudness kept": "削去响亮的瞬间，响度不变",
"the last step: no peak over the ceiling": "最后一步：没有峰值超过上限",
"Below the frequency the side (L − R) is taken out, as much as asked; above it nothing changes. The side is high-passed with a zero-phase filter and the mid left as it is, so the bass and the kick sit in the centre and the stereo stays where it lives. Shaumarov's first tool on the instrument bus and the master.": "低于该频率时按要求去掉侧声道（L − R），高于它则什么都不变。侧声道经过零相位滤波，中声道保持原样，于是贝斯和底鼓坐在中央，立体声留在它本来的位置。这是 Shaumarov 在乐器总线和母带上的第一件工具。",
"A gentle compressor before anything else, as Shaumarov prepares a voice or a mix: only the loud moments lose the dB asked (its threshold found for that), the sharpest transients pass, and the file comes back as loud as it came. No ceiling here: put the True-peak ceiling at the end of the way.": "放在一切之前的温和压缩器，正如 Shaumarov 处理人声或混音的准备步骤：只有响亮的瞬间减少所要求的 dB（为此寻找阈值），最尖锐的瞬态通过，文件以原来的响度返回。这里没有上限：把真峰值上限放在路径的末尾。",
"An oversampled lookahead limiter, its ceiling checked by a true-peak meter. «as it came» only catches the overs at the file's own loudness; a loudness target drives into it (at most 6 dB of limiting). Shaumarov ends the master at about −0.5 dBTP.": "带过采样和前瞻的限幅器，其上限由真峰值表核对。「保持原响度」只在文件自身的响度下捕捉超出部分；响度目标会推入其中（限幅最多 6 dB）。Shaumarov 的母带收尾约在 −0.5 dBTP。",
"Below, Hz": "低于，Hz",
"Shave, dB": "削减，dB",
"Attack, ms": "起音，ms",
"Release, ms": "释放，ms",
"Ceiling, dBTP": "上限，dBTP",
"The frequency under which the stereo goes to the middle": "立体声在此频率以下归于中央",
"How much of the side under it goes: all of it, or a part": "其下的侧声道去掉多少：全部或一部分",
"How much the loud moments lose": "响亮的瞬间减少多少",
"How fast it takes hold: slower lets more of the transients through": "抓取的速度：越慢放过越多瞬态",
"No peak over it, between the samples too": "其上没有峰值，样本之间也没有",
"The file's own loudness, or a target to drive to": "文件自身的响度，或要推向的目标",
"Mono below {#0} Hz": "{0} Hz 以下单声道",
"Mono below {#0} Hz, {#1} %": "{0} Hz 以下单声道，{1} %",
"Peak glue, {#0} dB": "峰值粘合，{0} dB",
