// HERESY 1795: the DAW and the piano roll, a beta
"beta": "测试版",
"Beta: we make our songs here every day, and it is all still growing; what it keeps and how it looks may change in a later release.": "测试版：我们每天在这里做自己的歌，它仍在成长；它保存的内容和外观可能会在以后的版本中改变。",
